#!/usr/bin/env python3
"""Individually reviewed Cesi records; uncertainty and sheet identity retained."""
import importlib.util,json
from pathlib import Path
s=importlib.util.spec_from_file_location('campaign',Path(__file__).with_name('cesi-top100-20261010.py'));m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
AID='07441bd8-6663-4e16-963d-f16fc6cd35ba'
pages={d['url']:d for p in (m.RUN/'cesi-pages').glob('*.json') for d in [m.load(p)]}
rows=[]
def add(url,key,title,museum,date,kind='drawing',medium=None,dimensions=None,accession=None,role='primary',note='',image=None,rights=None,licence=None):
    page=pages[url];assert page['receipt']['status']==200
    raw,_=m.capture(url);assert b'Cesi' in raw or b'CESI' in raw
    rows.append(dict(provider='cesi-native',source_url=url,source_id=key,scheme='cesi-source-object',title=title,date=date,creator='Bartolomeo Cesi' if role=='primary' else 'Attributed to Bartolomeo Cesi',artist_id=AID,artist_name='Bartolomeo Cesi',artist_url=None,metadata=dict(source_page_file=str((m.RUN/'cesi-pages'/(m.sha(url.encode())[:16]+'.json')).relative_to(m.ROOT)),editorial_note=note),fields=dict(Media=medium,Dimensions=dimensions),receipt=page['receipt'],image_url=image,rights_label=rights or 'Image reuse not established; metadata only',rights_status='cc0' if licence and '/zero/' in licence else 'public_domain' if image else 'unknown',license_url=licence,rights_basis='Explicit native museum image reuse statement retained with object record.' if image else None,artwork_id=m.uid('artwork/'+key),state='new',image_needed=bool(image),add_holding=True,institution_id=museum,work_type=kind,attribution_role=role,accession=accession,selection_basis='User-requested deep Cesi review; documented institutional collection object.',identity_confidence=.98,identity_basis='Individually read institutional object/collection record; original inventory, physical sheet identity, qualifications and unknown dates preserved.',editorial_note=note))
def dated(first,last,display,precision='range'):return dict(first=first,last=last,display=display,precision=precision)
u='https://www.getty.edu/art/collection/object/107VNY'
raw,rc=m.capture(u);sp=m.BeautifulSoup(raw,'html.parser');d=json.loads(sp.select_one('script[type="application/ld+json"]').get_text())
assert d['identifier']==['98.GB.1'] and d['creator'][0]['name']=='Bartolomeo Cesi' and d['license']=='http://creativecommons.org/publicdomain/zero/1.0/'
add(u,'getty/107VNY',d['name'],'62fb1e52-07ff-50bd-8eeb-95ea5bf4af1c',dated(1590,1599,'about 1590s','circa_range'),medium=d['material'],dimensions=d['size'],accession='98.GB.1',image=d['thumbnailUrl'].replace('!300,300','!1600,1600'),rights='Getty Open Content: CC0',licence='https://creativecommons.org/publicdomain/zero/1.0/')
