u='https://www.museedegrenoble.fr/oeuvre/2572/1922-etude-d-un-homme-drape-assis-les-mains-appuyees-sur-un-baton.htm'
add(u,'grenoble/2572',"Etude d'un homme drapé assis, les mains appuyées sur un bâton",'76d4de95-1650-486a-ba44-45461b8d44da',dated(1601,1700,'XVIIe siècle','century'),medium='Red chalk with white chalk highlights; brown-ink framing line on lined green-grey laid paper',dimensions='18.5 × 13.3 cm',note='Source gives a century, retained without narrowing to the artist lifespan. No exact corresponding painting is established by the museum. Photo credit: VILLE DE GRENOBLE / MUSÉE DE GRENOBLE-J.L. LACROIX.',image='https://images.navigart.fr/1000/5C/86/5C86052.jpg',rights='Domaine public, Domaine public',licence='https://creativecommons.org/publicdomain/mark/1.0/')
