add(u,'rijksmuseum/200118126','Studie van een jongeman','b6a5755d-157e-4ebe-a5a9-3bc52964ebf5',dated(1607,1615,'1607–1615'),medium='Red and white chalk on blue paper',dimensions='353 × 240 mm',accession='RP-T-1967-68(R)',note='Recto of a physical sheet with a related verso study. One catalogue object retained, no separate verso artwork created. Probable preparation for a fresco, not an asserted identification.',image='https://iiif.micr.io/seAsX/full/!1600,1600/0/default.jpg',rights='Publiek domein',licence='https://creativecommons.org/publicdomain/mark/1.0/')
u='https://collections.louvre.fr/en/ark:/53355/cl020004994'
add(u,'louvre/cl020004994','Jeune homme assis, tenant un livre','355fdf89-aee5-4066-a0f3-fd4cfc2a13ae',None,medium='Red chalk and white chalk on blue paper, squared in black chalk',dimensions='17.1 × 15.9 cm',accession='INV 8035, Recto',note='Museum identifies this as a study for a singer in the Certosa di Maggiano vault completed in 1594. Completion of the fresco is contextual evidence, not an exact drawing creation date. Former Carracci-school attribution preserved in source. Photograph rights not cleared.')
