add(u,'genova/47771','Compianto su Cristo morto (recto) / Una testa e un volto virili di profilo (verso)','396e1957-9e64-525c-86e4-7e85d422ffc6',None,medium='Pen and ink on beige paper, squared in black pencil',dimensions='187 × 272 mm',accession='D 1226',role='attributed_to',note='Native AUTS field says attribuito. Recto and verso remain one sheet, related to the Certosa Lamentation painting. Native bounds repeat the artist lifespan and are retained only as source evidence, not creation years.')
