    add(u,'bologna-caption/'+key,title,'1cfa0c7f-e32b-54ac-9bfc-362fe6c7f4c3',None,'painting',note=note+' No creation date or inventory is given by this source. Exhibition ended in April 2026; no present-display assertion.')
